replacement = r'''  async function dashboardSettings(host){
    const {items} = await api('admin/contacts');
    const typeLabels = {phone:'هاتف', whatsapp:'واتساب', email:'بريد إلكتروني', location:'موقع', hours:'ساعات العمل', custom:'مخصص'};
    const typeOptions = Object.entries(typeLabels).map(([value,label]) => `<option value="${value}">${label}</option>`).join('');
    const contactTable = () => `<div class="table-scroll"><table class="data-table"><thead><tr><th>النوع</th><th>العنوان</th><th>القيمة</th><th>التفصيل</th><th>الترتيب</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${items.length ? items.map((item) => `<tr><td>${esc(typeLabels[item.type] || item.type)}</td><td>${esc(item.title_ar)}</td><td dir="ltr">${esc(item.value)}</td><td>${esc(item.description_ar || '—')}</td><td>${esc(item.sort_order)}</td><td>${status(item.status)}</td><td><button class="btn btn-outline btn-sm" data-contact-edit="${item.id}">تعديل</button> <button class="btn btn-outline btn-sm" data-contact-status="${item.id}" data-status-value="${item.status === 'active' ? 'inactive' : 'active'}">${item.status === 'active' ? 'إيقاف' : 'تفعيل'}</button></td></tr>`).join('') : `<tr><td colspan="7">${empty('لا توجد قنوات تواصل بعد.')}</td></tr>`}</tbody></table></div>`;
    host.innerHTML = `${dashTitle('الإعدادات','إدارة هوية الموقع وقنوات التواصل من مكان واحد.')}
      <section class="panel"><div class="panel-head"><h3>اتصل بنا</h3><span class="muted">القنوات النشطة فقط تظهر للزوار في صفحة اتصل بنا.</span></div><div class="panel-body"><form id="contact-create" class="form-grid"><div class="field"><label>النوع</label><select name="type" required>${typeOptions}</select></div><div class="field"><label>العنوان</label><input name="title_ar" placeholder="الهاتف أو البريد" required></div><div class="field"><label>القيمة</label><input name="value" placeholder="+967... أو support@example.com" required></div><div class="field"><label>التفصيل</label><input name="description_ar" placeholder="ساعات العمل أو وصف القناة"></div><div class="field"><label>الأيقونة</label><input name="icon" value="bi-info-circle" placeholder="bi-telephone"></div><div class="field"><label>الترتيب</label><input name="sort_order" type="number" min="0" max="999" value="1" required></div><div class="field"><label>الحالة</label><select name="status"><option value="active">نشط ويظهر للعامة</option><option value="inactive">موقوف ومخفي</option></select></div><div class="field"><label>&nbsp;</label><button class="btn btn-primary" type="submit">إضافة قناة التواصل</button></div></form></div></section>
      <section class="panel" style="margin-top:18px"><div class="panel-head"><h3>قنوات التواصل الحالية (${items.length})</h3></div><div class="panel-body">${contactTable()}</div></section>`;
    $('#contact-create', host)?.addEventListener('submit', async (event) => { event.preventDefault(); try { await api('admin/contacts', { method:'POST', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); showToast('تمت إضافة قناة التواصل.','success'); dashboardSettings(host); } catch (error) { showToast(error.message,'error'); } });
    $$('[data-contact-status]', host).forEach((button) => button.addEventListener('click', async () => { try { await api(`admin/contacts/${button.dataset.contactStatus}/status`, { method:'PUT', body:JSON.stringify({status:button.dataset.statusValue}) }); showToast('تم تحديث حالة قناة التواصل.','success'); dashboardSettings(host); } catch (error) { showToast(error.message,'error'); } }));
    $$('[data-contact-edit]', host).forEach((button) => button.addEventListener('click', () => { const item = items.find((entry) => Number(entry.id) === Number(button.dataset.contactEdit)); if (!item) return; const layer = modal(`<h3>تعديل قناة التواصل</h3><form id="contact-edit-form" class="form-grid"><div class="field"><label>النوع</label><select name="type">${Object.entries(typeLabels).map(([value,label]) => `<option value="${value}" ${item.type === value ? 'selected' : ''}>${label}</option>`).join('')}</select></div><div class="field"><label>العنوان</label><input name="title_ar" value="${esc(item.title_ar)}" required></div><div class="field"><label>القيمة</label><input name="value" value="${esc(item.value)}" required></div><div class="field"><label>التفصيل</label><input name="description_ar" value="${esc(item.description_ar || '')}"></div><div class="field"><label>الأيقونة</label><input name="icon" value="${esc(item.icon || 'bi-info-circle')}"></div><div class="field"><label>الترتيب</label><input name="sort_order" type="number" min="0" max="999" value="${esc(item.sort_order)}" required></div><div class="field"><label>الحالة</label><select name="status"><option value="active" ${item.status === 'active' ? 'selected' : ''}>نشط ويظهر للعامة</option><option value="inactive" ${item.status === 'inactive' ? 'selected' : ''}>موقوف ومخفي</option></select></div><div class="modal-actions"><button class="btn btn-primary" type="submit">حفظ التعديل</button><button class="btn btn-outline" type="button" data-modal-close>إلغاء</button></div></form>`,'contact-edit-dialog'); $('[data-modal-close]', layer)?.addEventListener('click', closeModal); $('#contact-edit-form', layer)?.addEventListener('submit', async (event) => { event.preventDefault(); try { await api(`admin/contacts/${item.id}`, { method:'PUT', body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); closeModal(); showToast('تم تعديل قناة التواصل.','success'); dashboardSettings(host); } catch (error) { showToast(error.message,'error'); } }); }));
  }
  async function dashboardContactMessages(host){
    const {items} = await api('admin/contact-messages');
    const labels = {new:'جديدة', in_progress:'قيد المتابعة', resolved:'تمت المعالجة', spam:'مزعجة'};
    const tone = {new:'active', in_progress:'pending', resolved:'confirmed', spam:'cancelled'};
    host.innerHTML = `${dashTitle('رسائل اتصل بنا','راجع الرسائل الواردة من نموذج الموقع وحدّث حالتها من مكان مستقل.')}
      <section class="panel"><div class="panel-head"><div><h3>الرسائل الواردة (${items.length})</h3><span class="muted">تظهر هنا بيانات الاسم ورقم الهاتف والبريد والموضوع والمحتوى.</span></div></div><div class="panel-body"><div class="table-scroll"><table class="data-table contact-messages-table"><thead><tr><th>التاريخ</th><th>الاسم</th><th>الهاتف</th><th>البريد</th><th>الموضوع</th><th>المحتوى</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${items.length ? items.map((item) => `<tr><td>${dateTime(item.created_at)}</td><td>${esc(item.full_name)}</td><td dir="ltr">${esc(item.phone)}</td><td dir="ltr">${esc(item.email)}</td><td>${esc(item.subject)}</td><td class="contact-message-preview">${esc(item.message)}</td><td><span class="status ${tone[item.status] || 'active'}">${esc(labels[item.status] || item.status)}</span></td><td><div class="table-actions"><button class="btn btn-outline btn-sm" data-contact-message-view="${item.id}">عرض</button><button class="btn btn-outline btn-sm" data-contact-message-status="${item.id}">الحالة</button></div></td></tr>`).join('') : `<tr><td colspan="8">${empty('لا توجد رسائل تواصل بعد.')}</td></tr>`}</tbody></table></div></div></section>`;
    $$('[data-contact-message-view]', host).forEach((button) => button.addEventListener('click', () => { const item = items.find((entry) => Number(entry.id) === Number(button.dataset.contactMessageView)); if (!item) return; modal(`<h3>${esc(item.subject || 'رسالة من الموقع')}</h3><div class="message-detail-grid"><div><span>الاسم</span><b>${esc(item.full_name)}</b></div><div><span>الهاتف</span><b dir="ltr">${esc(item.phone)}</b></div><div><span>البريد</span><b dir="ltr">${esc(item.email)}</b></div><div><span>التاريخ</span><b>${dateTime(item.created_at)}</b></div></div><div class="contact-message-full"><b>المحتوى</b><p>${esc(item.message)}</p></div><button class="btn btn-outline" type="button" data-modal-close>إغلاق</button>`,'contact-message-detail-dialog'); $('[data-modal-close]')?.addEventListener('click', closeModal); }));
    $$('[data-contact-message-status]', host).forEach((button) => button.addEventListener('click', () => { const item = items.find((entry) => Number(entry.id) === Number(button.dataset.contactMessageStatus)); if (!item) return; const layer = modal(`<h3>تغيير حالة رسالة التواصل</h3><p><b>${esc(item.full_name)}</b> — ${esc(item.subject)}</p><form id="contact-message-status-form"><select name="status" class="field-input">${Object.entries(labels).map(([value,label]) => `<option value="${value}" ${item.status === value ? 'selected' : ''}>${label}</option>`).join('')}</select><div class="modal-actions"><button class="btn btn-primary" type="submit">حفظ الحالة</button><button class="btn btn-outline" type="button" data-modal-close>إلغاء</button></div></form>`,'contact-message-status-dialog'); $('[data-modal-close]', layer)?.addEventListener('click', closeModal); $('#contact-message-status-form', layer)?.addEventListener('submit', async (event) => { event.preventDefault(); try { await api(`admin/contact-messages/${item.id}/status`, {method:'PUT', body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); closeModal(); showToast('تم تحديث حالة رسالة التواصل.','success'); dashboardContactMessages(host); } catch (error) { showToast(error.message,'error'); } }); }));
  }
'''
text = text[:start] + replacement + text[end:]
